        const DISPLAY_PREFS_KEY = 'service-center.display.v1';
        const DISPLAY_THEMES = ['kinet', 'azure', 'sage'];
        const DISPLAY_DEFAULTS = { scale: 100, density: 'auto', theme: 'kinet' };

        function appTranslate(key, fallback = '', params = null) {
            let template = Object.prototype.hasOwnProperty.call(APP_TRANSLATIONS, key)
                ? APP_TRANSLATIONS[key]
                : (fallback || key);
            if (params && typeof params === 'object') {
                Object.entries(params).forEach(([paramKey, paramValue]) => {
                    const token = new RegExp(`\\{${paramKey}\\}`, 'g');
                    template = String(template).replace(token, String(paramValue ?? ''));
                });
            }
            return String(template);
        }

        window.AppI18n = {
            lang: APP_LANGUAGE,
            locale: APP_LOCALE,
            strings: APP_TRANSLATIONS,
            t: appTranslate
        };

        const APP_TOAST_ICONS = {
            success: 'fa-circle-check',
            info: 'fa-circle-info',
            warning: 'fa-triangle-exclamation',
            danger: 'fa-circle-exclamation'
        };
        const APP_TOAST_TITLES = {
            success: appTranslate('toast.success', 'Success'),
            info: appTranslate('toast.info', 'Information'),
            warning: appTranslate('toast.warning', 'Warning'),
            danger: appTranslate('toast.error', 'Error')
        };

        function getAppToastContainer() {
            return document.getElementById('appToastContainer');
        }

        function appToast(message, type = 'info', options = {}) {
            const container = getAppToastContainer();
            if (!container) {
                return;
            }
            const safeType = ['success', 'info', 'warning', 'danger'].includes(type) ? type : 'info';
            const delay = Number.isFinite(Number(options.delay)) ? Number(options.delay) : 3000;
            const icon = APP_TOAST_ICONS[safeType] || APP_TOAST_ICONS.info;

            const toastEl = document.createElement('div');
            toastEl.className = `toast app-toast app-toast-${safeType} align-items-center border-0`;
            toastEl.setAttribute('role', 'alert');
            toastEl.setAttribute('aria-live', 'assertive');
            toastEl.setAttribute('aria-atomic', 'true');
            toastEl.dataset.bsAutohide = options.autohide === false ? 'false' : 'true';
            toastEl.dataset.bsDelay = String(delay);

            const body = document.createElement('div');
            body.className = 'toast-body';
            const iconNode = document.createElement('i');
            iconNode.className = `fas ${icon}`;
            const iconWrap = document.createElement('span');
            iconWrap.className = 'app-toast-icon';
            iconWrap.appendChild(iconNode);
            const copyNode = document.createElement('div');
            copyNode.className = 'app-toast-copy';
            const titleNode = document.createElement('span');
            titleNode.className = 'app-toast-title';
            titleNode.textContent = options.title || APP_TOAST_TITLES[safeType] || APP_TOAST_TITLES.info;
            const textNode = document.createElement('span');
            textNode.className = 'app-toast-message';
            if (options && options.html === true) {
                textNode.innerHTML = String(message ?? '');
            } else {
                textNode.textContent = String(message ?? '');
            }
            copyNode.appendChild(titleNode);
            copyNode.appendChild(textNode);
            const closeBtn = document.createElement('button');
            closeBtn.type = 'button';
            closeBtn.className = 'app-toast-close';
            closeBtn.setAttribute('aria-label', appTranslate('common.close', 'Close'));
            closeBtn.innerHTML = '<i class="fas fa-xmark"></i>';
            closeBtn.addEventListener('click', () => {
                const instance = bootstrap.Toast.getInstance(toastEl);
                if (instance) {
                    instance.hide();
                } else {
                    toastEl.remove();
                }
            });
            body.appendChild(iconWrap);
            body.appendChild(copyNode);
            body.appendChild(closeBtn);
            toastEl.appendChild(body);

            container.appendChild(toastEl);
            const instance = new bootstrap.Toast(toastEl, {
                autohide: options.autohide === false ? false : true,
                delay
            });
            toastEl.addEventListener('hidden.bs.toast', () => {
                toastEl.remove();
            }, { once: true });
            instance.show();
        }

        function appConfirm(options = {}) {
            const modalEl = document.getElementById('appConfirmModal');
            const titleEl = document.getElementById('appConfirmModalTitle');
            const bodyEl = document.getElementById('appConfirmModalBody');
            const iconEl = document.getElementById('appConfirmModalIcon');
            const cancelBtn = document.getElementById('appConfirmModalCancel');
            const acceptBtn = document.getElementById('appConfirmModalAccept');

            if (!modalEl || !titleEl || !bodyEl || !cancelBtn || !acceptBtn) {
                return Promise.resolve(window.confirm(options.message || appTranslate('confirm.are_you_sure', 'Are you sure?')));
            }

            const variant = ['primary', 'danger', 'warning', 'success'].includes(options.variant) ? options.variant : 'primary';
            titleEl.textContent = options.title || appTranslate('confirm.please_confirm', 'Please confirm');
            bodyEl.textContent = options.message || appTranslate('confirm.are_you_sure', 'Are you sure?');
            acceptBtn.textContent = options.confirmText || appTranslate('common.confirm', 'Confirm');
            cancelBtn.textContent = options.cancelText || appTranslate('common.cancel', 'Cancel');
            acceptBtn.className = `btn btn-${variant} btn-sm`;
            cancelBtn.className = 'btn btn-outline-secondary btn-sm';
            iconEl.className = variant === 'danger' ? 'fas fa-triangle-exclamation' : 'fas fa-circle-question';
            const iconWrap = iconEl.parentElement;
            if (iconWrap) {
                iconWrap.className = `app-confirm-icon is-${variant}`;
            }

            const modal = bootstrap.Modal.getOrCreateInstance(modalEl, { backdrop: 'static', keyboard: true });

            return new Promise((resolve) => {
                let resolved = false;
                const done = (value) => {
                    if (resolved) return;
                    resolved = true;
                    cleanup();
                    resolve(value);
                };
                const onAccept = () => {
                    modal.hide();
                    done(true);
                };
                const onCancel = () => {
                    modal.hide();
                    done(false);
                };
                const onHidden = () => done(false);
                const cleanup = () => {
                    acceptBtn.removeEventListener('click', onAccept);
                    cancelBtn.removeEventListener('click', onCancel);
                    modalEl.removeEventListener('hidden.bs.modal', onHidden);
                };
                acceptBtn.addEventListener('click', onAccept);
                cancelBtn.addEventListener('click', onCancel);
                modalEl.addEventListener('hidden.bs.modal', onHidden);
                modal.show();
            });
        }

        function createUnsavedChangesGuard(options = {}) {
            const config = {
                message: options.message || appTranslate('guard.unsaved_changes_message', 'You have unsaved changes. Leave this page without saving?'),
                title: options.title || appTranslate('guard.unsaved_changes_title', 'Unsaved changes'),
                confirmText: options.confirmText || appTranslate('guard.leave_page', 'Leave page'),
                cancelText: options.cancelText || appTranslate('guard.stay', 'Stay'),
                variant: options.variant || 'warning',
                isDirty: typeof options.isDirty === 'function' ? options.isDirty : () => false,
            };

            const state = {
                enabled: true,
                suppressBeforeUnload: false,
                navigationInProgress: false,
            };

            function shouldBypassAnchor(anchor, event) {
                if (!anchor) return true;
                if (event && (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
                    return true;
                }
                if (anchor.hasAttribute('download')) return true;
                if (anchor.dataset.skipUnsavedGuard === 'true') return true;
                const target = String(anchor.getAttribute('target') || '').trim().toLowerCase();
                if (target === '_blank') return true;
                const rawHref = String(anchor.getAttribute('href') || '').trim();
                if (!rawHref || rawHref === '#' || rawHref.startsWith('#')) return true;
                const lowerHref = rawHref.toLowerCase();
                if (lowerHref.startsWith('javascript:') || lowerHref.startsWith('mailto:') || lowerHref.startsWith('tel:')) return true;
                return false;
            }

            async function confirmLeave() {
                if (typeof options.confirmLeave === 'function') {
                    try {
                        const result = options.confirmLeave();
                        return result && typeof result.then === 'function' ? await result : Boolean(result);
                    } catch (error) {
                        return false;
                    }
                }
                return appConfirm({
                    title: config.title,
                    message: config.message,
                    confirmText: config.confirmText,
                    cancelText: config.cancelText,
                    variant: config.variant
                });
            }

            function onBeforeUnload(event) {
                if (!state.enabled || state.suppressBeforeUnload) return;
                if (!config.isDirty()) return;
                event.preventDefault();
                // Browser-native text is restricted by modern browsers.
                event.returnValue = '';
            }

            async function onDocumentClick(event) {
                if (!state.enabled || state.navigationInProgress) return;
                if (!config.isDirty()) return;

                const anchor = event.target && event.target.closest ? event.target.closest('a[href]') : null;
                if (!anchor || shouldBypassAnchor(anchor, event)) return;

                let nextUrl;
                try {
                    nextUrl = new URL(anchor.href, window.location.href);
                } catch (error) {
                    return;
                }
                if (nextUrl.href === window.location.href) return;

                event.preventDefault();
                event.stopPropagation();
                state.navigationInProgress = true;
                const confirmed = await confirmLeave();
                if (confirmed) {
                    state.suppressBeforeUnload = true;
                    window.location.assign(nextUrl.href);
                    return;
                }
                state.navigationInProgress = false;
            }

            window.addEventListener('beforeunload', onBeforeUnload);
            document.addEventListener('click', onDocumentClick, true);

            return {
                dispose() {
                    window.removeEventListener('beforeunload', onBeforeUnload);
                    document.removeEventListener('click', onDocumentClick, true);
                },
                setEnabled(enabled) {
                    state.enabled = Boolean(enabled);
                },
                suppressNextBeforeUnload() {
                    state.suppressBeforeUnload = true;
                }
            };
        }

        window.AppUI = {
            toast: appToast,
            confirm: appConfirm,
            unsavedGuard: createUnsavedChangesGuard
        };

        function toAppDate(value) {
            if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
            if (value === null || value === undefined || value === '') return null;
            const parsed = new Date(value);
            return Number.isNaN(parsed.getTime()) ? null : parsed;
        }

        function formatAppDateTime(value, options = {}) {
            const date = toAppDate(value);
            if (!date) return options.fallback ?? 'n/a';
            return new Intl.DateTimeFormat(APP_LOCALE, {
                timeZone: APP_TIMEZONE,
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false,
                ...options
            }).format(date);
        }

        function formatAppTime(value, options = {}) {
            const date = toAppDate(value);
            if (!date) return options.fallback ?? 'n/a';
            return new Intl.DateTimeFormat(APP_LOCALE, {
                timeZone: APP_TIMEZONE,
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false,
                ...options
            }).format(date);
        }

        function formatAppDate(value, options = {}) {
            const date = toAppDate(value);
            if (!date) return options.fallback ?? 'n/a';
            return new Intl.DateTimeFormat(APP_LOCALE, {
                timeZone: APP_TIMEZONE,
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                ...options
            }).format(date);
        }

        window.AppTime = {
            timezone: APP_TIMEZONE,
            toDate: toAppDate,
            formatDateTime: formatAppDateTime,
            formatTime: formatAppTime,
            formatDate: formatAppDate,
        };

        function initTopbarClock() {
            const clockEl = document.getElementById('appTopbarClock');
            const timeEl = document.getElementById('appTopbarClockTime');
            const dateEl = document.getElementById('appTopbarClockDate');
            if (!timeEl) return;
            if (clockEl) clockEl.title = appTranslate('common.current_application_time', 'Current application time');

            const tick = () => {
                const now = new Date();
                timeEl.textContent = AppTime.formatTime(now);
                if (dateEl) dateEl.textContent = AppTime.formatDate(now);
            };

            tick();
            window.setInterval(tick, 1000);
        }

        const APP_PERF_CACHE_VERSION = "v1";
        const APP_PERF_INFLIGHT = new Map();

        function appPerfReadCache(key) {
            if (!key) return null;
            try {
                const raw = sessionStorage.getItem(`perf_cache:${APP_PERF_CACHE_VERSION}:${key}`);
                if (!raw) return null;
                const parsed = JSON.parse(raw);
                if (!parsed || typeof parsed !== 'object' || parsed.data === undefined) return null;
                return parsed;
            } catch (error) {
                return null;
            }
        }

        function appPerfWriteCache(key, data) {
            if (!key) return;
            try {
                sessionStorage.setItem(
                    `perf_cache:${APP_PERF_CACHE_VERSION}:${key}`,
                    JSON.stringify({ ts: Date.now(), data })
                );
            } catch (error) {
                // ignore sessionStorage limits
            }
        }

        function appPerfSetSkeleton(target, enabled, options = {}) {
            const el = typeof target === 'string' ? document.querySelector(target) : target;
            if (!el) return;
            const isEnabled = Boolean(enabled);
            el.classList.toggle('perf-skeleton', isEnabled);
            el.classList.toggle('perf-skeleton-soft', Boolean(options.soft) && isEnabled);
            el.setAttribute('aria-busy', isEnabled ? 'true' : 'false');
        }

        function appPerfObserveLazy(target, callback, options = {}) {
            const el = typeof target === 'string' ? document.querySelector(target) : target;
            if (!el || typeof callback !== 'function') return () => {};

            let disposed = false;
            const once = options.once !== false;
            const run = () => {
                if (disposed) return;
                if (once) disposed = true;
                callback();
            };

            if (!('IntersectionObserver' in window)) {
                run();
                return () => {};
            }

            const observer = new IntersectionObserver((entries) => {
                const isVisible = entries.some((entry) => entry.isIntersecting || entry.intersectionRatio > 0);
                if (!isVisible) return;
                run();
                if (once) observer.disconnect();
            }, {
                root: options.root || null,
                rootMargin: options.rootMargin || '140px',
                threshold: options.threshold ?? 0.01
            });
            observer.observe(el);
            return () => {
                disposed = true;
                observer.disconnect();
            };
        }

        async function appPerfSWR(key, fetcher, options = {}) {
            if (typeof fetcher !== 'function') {
                throw new Error('SWR fetcher must be a function');
            }
            const ttlMs = Math.max(0, Number(options.ttlMs ?? 15000));
            const now = Date.now();
            const force = Boolean(options.force);
            const cached = key ? appPerfReadCache(key) : null;
            const cacheAge = cached ? (now - Number(cached.ts || 0)) : Number.POSITIVE_INFINITY;
            const hasFreshCache = Boolean(cached) && cacheAge <= ttlMs;

            if (cached && typeof options.onCached === 'function') {
                try {
                    options.onCached(cached.data, { stale: !hasFreshCache, ts: Number(cached.ts || 0), ageMs: cacheAge });
                } catch (error) {
                    console.debug('SWR onCached callback error', error);
                }
            }

            if (cached && hasFreshCache && !force) {
                return { data: cached.data, source: 'cache-fresh', ts: Number(cached.ts || 0), ageMs: cacheAge };
            }

            const requestKey = key || `anon:${Math.random().toString(36).slice(2)}`;
            let inflight = APP_PERF_INFLIGHT.get(requestKey);
            if (!inflight) {
                inflight = Promise.resolve()
                    .then(() => fetcher())
                    .then((data) => {
                        if (key) appPerfWriteCache(key, data);
                        return data;
                    })
                    .finally(() => {
                        APP_PERF_INFLIGHT.delete(requestKey);
                    });
                APP_PERF_INFLIGHT.set(requestKey, inflight);
            }

            if (cached && !force) {
                inflight.then((freshData) => {
                    if (typeof options.onFresh === 'function') {
                        options.onFresh(freshData, { stale: false, ts: Date.now(), ageMs: 0 });
                    }
                }).catch((error) => {
                    if (typeof options.onError === 'function') options.onError(error, { hadCache: true });
                });
                return { data: cached.data, source: 'cache-stale', ts: Number(cached.ts || 0), ageMs: cacheAge };
            }

            try {
                const freshData = await inflight;
                if (typeof options.onFresh === 'function') {
                    options.onFresh(freshData, { stale: false, ts: Date.now(), ageMs: 0 });
                }
                return { data: freshData, source: 'network', ts: Date.now(), ageMs: 0 };
            } catch (error) {
                if (typeof options.onError === 'function') options.onError(error, { hadCache: Boolean(cached) });
                if (cached) return { data: cached.data, source: 'cache-fallback', ts: Number(cached.ts || 0), ageMs: cacheAge };
                throw error;
            }
        }

        window.AppPerf = {
            readCache: appPerfReadCache,
            writeCache: appPerfWriteCache,
            setSkeleton: appPerfSetSkeleton,
            observeLazy: appPerfObserveLazy,
            swr: appPerfSWR
        };

        function clamp(value, min, max, fallback) {
            const num = Number(value);
            if (!Number.isFinite(num)) return fallback;
            return Math.min(max, Math.max(min, num));
        }

        function loadDisplayPrefs() {
            const prefs = { ...DISPLAY_DEFAULTS };
            try {
                const raw = localStorage.getItem(DISPLAY_PREFS_KEY);
                if (!raw) return prefs;
                const parsed = JSON.parse(raw);
                prefs.scale = clamp(parsed.scale, 85, 130, DISPLAY_DEFAULTS.scale);
                if (['auto', 'comfortable', 'compact', 'condensed'].includes(parsed.density)) {
                    prefs.density = parsed.density;
                }
                const savedTheme = parsed.theme === 'default' ? 'kinet' : parsed.theme;
                if (DISPLAY_THEMES.includes(savedTheme)) {
                    prefs.theme = savedTheme;
                }
            } catch (error) {
                return prefs;
            }
            return prefs;
        }

        function saveDisplayPrefs(prefs) {
            try {
                localStorage.setItem(DISPLAY_PREFS_KEY, JSON.stringify(prefs));
            } catch (error) {
                // ignore localStorage limitations
            }
        }

        const displayPrefs = loadDisplayPrefs();

        function applyViewportDensity() {
            const root = document.documentElement;
            const width = window.innerWidth || document.documentElement.clientWidth || 0;
            const density = displayPrefs.density || 'auto';

            root.classList.remove('ui-compact', 'ui-condensed');

            if (density === 'auto') {
                root.classList.toggle('ui-compact', width > 0 && width < 1680);
                root.classList.toggle('ui-condensed', width > 0 && width < 1360);
                return;
            }

            if (density === 'compact') {
                root.classList.add('ui-compact');
                return;
            }

            if (density === 'condensed') {
                root.classList.add('ui-compact', 'ui-condensed');
            }
        }

        function syncDisplayControls() {
            const zoomRange = document.getElementById('display-zoom-range');
            const zoomValue = document.getElementById('display-zoom-value');
            const densitySelect = document.getElementById('display-density-select');
            const themeSelect = document.getElementById('display-theme-select');
            if (zoomRange) zoomRange.value = String(displayPrefs.scale);
            if (zoomValue) zoomValue.textContent = `${displayPrefs.scale}%`;
            if (densitySelect) densitySelect.value = displayPrefs.density;
            if (themeSelect) themeSelect.value = displayPrefs.theme;
        }

        function applyColorTheme() {
            const root = document.documentElement;
            root.classList.remove('ui-theme-kinet', 'ui-theme-azure', 'ui-theme-sage');
            if (displayPrefs.theme === 'kinet') {
                root.classList.add('ui-theme-kinet');
                return;
            }
            if (displayPrefs.theme === 'azure') {
                root.classList.add('ui-theme-azure');
                return;
            }
            if (displayPrefs.theme === 'sage') {
                root.classList.add('ui-theme-sage');
            }
        }

        function applyDisplayPrefs() {
            document.documentElement.style.setProperty('--ui-font-scale', (displayPrefs.scale / 100).toFixed(2));
            applyColorTheme();
            applyViewportDensity();
            syncDisplayControls();
            document.dispatchEvent(new CustomEvent('app:display-prefs-changed', { detail: { ...displayPrefs } }));
        }

        function initDisplaySettings() {
            const zoomRange = document.getElementById('display-zoom-range');
            const densitySelect = document.getElementById('display-density-select');
            const themeSelect = document.getElementById('display-theme-select');
            const resetBtn = document.getElementById('display-settings-reset');

            if (zoomRange) {
                zoomRange.addEventListener('input', (event) => {
                    displayPrefs.scale = clamp(event.target.value, 85, 130, DISPLAY_DEFAULTS.scale);
                    applyDisplayPrefs();
                    saveDisplayPrefs(displayPrefs);
                });
            }

            if (densitySelect) {
                densitySelect.addEventListener('change', (event) => {
                    const mode = event.target.value;
                    displayPrefs.density = ['auto', 'comfortable', 'compact', 'condensed'].includes(mode) ? mode : 'auto';
                    applyDisplayPrefs();
                    saveDisplayPrefs(displayPrefs);
                });
            }

            if (themeSelect) {
                themeSelect.addEventListener('change', (event) => {
                    const nextTheme = event.target.value;
                    displayPrefs.theme = DISPLAY_THEMES.includes(nextTheme) ? nextTheme : DISPLAY_DEFAULTS.theme;
                    applyDisplayPrefs();
                    saveDisplayPrefs(displayPrefs);
                });
            }

            if (resetBtn) {
                resetBtn.addEventListener('click', () => {
                    displayPrefs.scale = DISPLAY_DEFAULTS.scale;
                    displayPrefs.density = DISPLAY_DEFAULTS.density;
                    displayPrefs.theme = DISPLAY_DEFAULTS.theme;
                    applyDisplayPrefs();
                    saveDisplayPrefs(displayPrefs);
                });
            }

            syncDisplayControls();
        }

        function toggleSidebar(forceOpen) {
            if (typeof forceOpen === 'boolean') {
                document.body.classList.toggle('sidebar-open', forceOpen);
                return;
            }
            document.body.classList.toggle('sidebar-open');
        }

        function toggleTopbarUserMenu() {
            const dropdown = document.getElementById('topbarUserDropdown');
            const btn = document.querySelector('.topbar-avatar-chip');
            if (!dropdown || !btn) return;
            const isOpen = dropdown.classList.toggle('is-open');
            btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
            if (isOpen) {
                const rect = btn.getBoundingClientRect();
                dropdown.style.top = (rect.bottom + 6) + 'px';
                dropdown.style.right = (window.innerWidth - rect.right) + 'px';
                document.addEventListener('mousedown', closeTopbarUserMenuOnClick);
            } else {
                document.removeEventListener('mousedown', closeTopbarUserMenuOnClick);
            }
        }

        function closeTopbarUserMenuOnClick(e) {
            const menu = document.querySelector('.topbar-avatar-menu');
            if (!menu || menu.contains(e.target)) return;
            const dropdown = document.getElementById('topbarUserDropdown');
            const btn = document.querySelector('.topbar-avatar-chip');
            if (dropdown) {
                dropdown.classList.remove('is-open');
                if (btn) btn.setAttribute('aria-expanded', 'false');
                document.removeEventListener('mousedown', closeTopbarUserMenuOnClick);
            }
        }

        window.addEventListener('resize', function() {
            applyViewportDensity();
            document.dispatchEvent(new CustomEvent('app:display-prefs-changed', { detail: { ...displayPrefs } }));
            if (window.innerWidth > 1024) {
                document.body.classList.remove('sidebar-open');
            }
        });

        if (window.visualViewport && window.visualViewport.addEventListener) {
            window.visualViewport.addEventListener('resize', () => {
                applyViewportDensity();
                document.dispatchEvent(new CustomEvent('app:display-prefs-changed', { detail: { ...displayPrefs } }));
            });
        }

        const APP_USER_ROLE = "viewer";
        const ADVANCED_MODE_KEY = 'service-center.advanced-mode.v1';

        function _updateAdvancedModeBtn(isAdvanced) {
            const btn = document.getElementById('advancedModeBtn');
            if (!btn) return;
            const labelOn  = appTranslate('display.simple_mode', 'Jednoduchý režim');
            const labelOff = appTranslate('display.advanced_mode', 'Pokročilý režim');
            btn.title = isAdvanced ? labelOn : labelOff;
            btn.setAttribute('aria-label', btn.title);
            btn.classList.toggle('is-active', isAdvanced);
        }

        function initAdvancedMode() {
            const defaultAdvanced = APP_USER_ROLE !== 'viewer';
            let isAdvanced = defaultAdvanced;
            try {
                const stored = localStorage.getItem(ADVANCED_MODE_KEY + '.' + APP_USER_ROLE);
                if (stored !== null) isAdvanced = stored === 'true';
            } catch (e) {}
            document.body.classList.toggle('mode-advanced', isAdvanced);
            _updateAdvancedModeBtn(isAdvanced);
        }

        function toggleAdvancedMode() {
            const isAdvanced = !document.body.classList.contains('mode-advanced');
            document.body.classList.toggle('mode-advanced', isAdvanced);
            try {
                localStorage.setItem(ADVANCED_MODE_KEY + '.' + APP_USER_ROLE, String(isAdvanced));
            } catch (e) {}
            _updateAdvancedModeBtn(isAdvanced);
        }

        applyDisplayPrefs();
        initDisplaySettings();
        initTopbarClock();
        initAdvancedMode();
        document.addEventListener('contextmenu', function(e) { e.preventDefault(); });
    


(function() {
const STATUS_COLORS = { online: '#0f9d69', warn: '#e4a313', offline: '#cb3a42', unknown: '#94a3b8' };
const TIER_ORDER    = { offline: 0, warn: 1, online: 2, unknown: 3 };

function STATUS_TIER_RAW(s) {
    if (!s) return 'unknown';
    const l = String(s).toLowerCase();
    if (l === 'online' || l === 'connected' || l === 'active' || l === 'quiet') return 'online';
    if (l === 'warn'   || l === 'warning'   || l === 'degraded' || l === 'stale' || l === 'auto_detach_pending') return 'warn';
    if (l === 'offline'|| l === 'disconnected' || l === 'inactive' || l === 'auto_detached') return 'offline';
    if (l === 'no_data' || l === 'unknown') return 'unknown';
    return 'unknown';
}
function SENSOR_TIER(sensor) {
    const tier = String((sensor && sensor.ui_tier) || '').toLowerCase();
    if (tier === 'online' || tier === 'warn' || tier === 'offline' || tier === 'unknown') return tier;
    return STATUS_TIER_RAW(sensor && (sensor.activity_status || sensor.status));
}
const STATUS_LABELS = {
    active: 'Aktívny', online: 'Online', connected: 'Online', quiet: 'Pokojný',
    warning: 'Upozornenie', warn: 'Upozornenie', degraded: 'Upozornenie', stale: 'Stagnujúci', auto_detach_pending: 'Odpája sa',
    offline: 'Offline', disconnected: 'Offline', inactive: 'Offline', auto_detached: 'Odpojený',
    no_data: 'Bez dát', unknown: 'Neznámy'
};
function SENSOR_STATUS_LABEL(sensor) {
    const raw = sensor && (sensor.activity_status || sensor.status);
    if (!raw) return 'Neznámy';
    return STATUS_LABELS[String(raw).toLowerCase()] || STATUS_LABELS[raw] || String(raw);
}

const MSKIP = new Set(['co2_last_calibration_ppm','days_to_next_calibration','co2_error','calibration_not_done','temperature_2_c','humidity_2_pct','pressure_pa','altitude_m']);
const MLABEL = {co2_1_ppm:'CO₂',temperature_1_c:'Teplota',humidity_1_pct:'Vlhkosť',battery_v_est:'Batéria',any_alarm_active:'Alarm',open_count:'Otvorenia'};
function mLabel(k) { return MLABEL[k] || k.replace(/_/g,' '); }
function mFmt(k, v) {
    if (typeof v === 'boolean') return [v ? 'ÁNO' : 'NIE', ''];
    const n = Number(v);
    if (!Number.isFinite(n)) return [String(v), ''];
    if (k.endsWith('_ppm'))   return [Math.round(n).toString(), 'ppm'];
    if (k.endsWith('_c'))     return [n.toFixed(1), '°C'];
    if (k.endsWith('_pct'))   return [Math.round(n).toString(), '%'];
    if (k.endsWith('_v_est') || k.endsWith('_v')) return [n.toFixed(2), 'V'];
    return [String(n), ''];
}
function buildMetricChipsHtml(s) {
    const vals = s.last_values || {};
    const entries = Object.entries(vals).filter(([k, v]) => !k.startsWith('_') && !MSKIP.has(k) && v !== null && v !== undefined);
    if (!entries.length) return '';
    return entries.slice(0, 4).map(([k, v]) => {
        const [val, unit] = mFmt(k, v);
        return '<span class="mview-metric-chip">' + esc(mLabel(k)) + ' <span class="mval">' + esc(val) + '</span>' + (unit ? '<span class="munit">' + esc(unit) + '</span>' : '') + '</span>';
    }).join('');
}
function esc(v) {
    return String(v == null ? '' : v)
        .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function geoOf(s) {
    const lat = parseFloat(s.gps_lat != null ? s.gps_lat : (s.latitude != null ? s.latitude : s.lat));
    const lng = parseFloat(s.gps_lng != null ? s.gps_lng : (s.longitude != null ? s.longitude : (s.lon != null ? s.lon : s.lng)));
    return Number.isFinite(lat) && Number.isFinite(lng) ? [lat, lng] : null;
}
function sensorId(s) { return s.eui || s.device_eui || s.sensor_id || ''; }

function timeAgo(ts) {
    if (!ts) return null;
    const d = new Date(ts);
    if (isNaN(d)) return null;
    const sec = Math.round((Date.now() - d) / 1000);
    if (sec < 10)  return 'práve teraz';
    if (sec < 60)  return 'pred ' + sec + ' s';
    const min = Math.round(sec / 60);
    if (min < 60)  return 'pred ' + min + ' min';
    return 'pred ' + Math.round(min / 60) + ' hod';
}
function valueLine(s) {
    const parts = [];
    if (s.last_values && typeof s.last_values === 'object') {
        const e = Object.entries(s.last_values)[0];
        if (e) parts.push(esc(e[0]) + ': ' + esc(e[1]));
    }
    const tsRaw = s.last_seen_timestamp || s.last_seen || s.last_message || s.updated_at || 0;
    const tsMs = tsRaw > 1e10 ? tsRaw : tsRaw * 1000;
    const ago = timeAgo(tsMs);
    if (ago) parts.push(ago);
    return parts.join(' \u00b7 ');
}

let mviewMap = null;
let mviewLayer = null;
let sensorMarkers = {};   // id → L.circleMarker
let allSensors = [];
let currentFilter = 'all';
let lastLoadTs = null;
let tickTimer = null;

/* ── Map ── */
const _mapViewKey = 'sc.map-view.v1';

function saveMapView() {
    if (!mviewMap) return;
    const c = mviewMap.getCenter();
    const z = mviewMap.getZoom();
    localStorage.setItem(_mapViewKey, JSON.stringify({ lat: c.lat, lng: c.lng, zoom: z }));
}

function restoreMapView() {
    try {
        const saved = localStorage.getItem(_mapViewKey);
        if (saved) {
            const v = JSON.parse(saved);
            return { lat: v.lat, lng: v.lng, zoom: v.zoom };
        }
    } catch (e) {}
    return { lat: 48.768, lng: 18.635, zoom: 13 };
}

function initMap() {
    if (typeof L === 'undefined') return;
    const el = document.getElementById('mview-map');
    if (!el) return;
    mviewMap = L.map(el, { zoomControl: true, attributionControl: true, scrollWheelZoom: true });
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19, attribution: '\u00a9 OpenStreetMap contributors'
    }).addTo(mviewMap);
    mviewLayer = L.layerGroup().addTo(mviewMap);

    // Restore saved default view or use default
    const view = restoreMapView();
    mviewMap.setView([view.lat, view.lng], view.zoom);

    // Right-click on map to set default view (manual save only, no auto-save)
    mviewMap.on('contextmenu', function(e) {
        L.DomEvent.preventDefault(e.originalEvent);
        L.DomEvent.stopPropagation(e.originalEvent);
        showCtx(e.originalEvent, [
            { icon: 'fa-map-pin', label: 'Nastaviť ako východzí pohľad',
                action: function() { saveMapView(); showMapToast('\u2713 Pohľad uložený', 2000); } },
        ]);
    });
}

// ── Marker helpers ────────────────────────────────────────────────────────────
const MARKER_PALETTE = ['#2563eb','#16a34a','#dc2626','#d97706','#7c3aed','#0891b2','#db2777','#374151','#f59e0b','#059669'];
const _markerUnlocked = {};  // id → true when drag is enabled
const _pendingLatLng  = {};  // id → {_origLat,_origLng,lat,lng} pending confirm

function makeMarkerIcon(color, unlocked) {
    const border = unlocked ? 'border:2.5px solid #eb7e17;' : 'border:2.5px solid rgba(255,255,255,.92);';
    return L.divIcon({
        html: '<div class="sc-map-pin" style="background:' + color + ';' + border + '"></div>',
        className: 'sc-map-marker',
        iconSize: [20, 20],
        iconAnchor: [10, 10],
        popupAnchor: [0, -14]
    });
}

let _mapToast = null;
function showMapToast(msg, ms) {
    const panel = document.querySelector('.mview-map-panel');
    if (!panel) return;
    if (_mapToast) _mapToast.remove();
    const el = document.createElement('div');
    el.className = 'sc-map-toast';
    el.textContent = msg;
    panel.style.position = 'relative';
    panel.appendChild(el);
    _mapToast = el;
    setTimeout(function() { if (el.parentNode) el.remove(); if (_mapToast === el) _mapToast = null; }, ms || 2200);
}

let _colorPopEl = null;
function closeColorPop() { if (_colorPopEl) { _colorPopEl.remove(); _colorPopEl = null; } }

function showColorPop(x, y, currentColor, onPick) {
    closeColorPop();
    const pop = document.createElement('div');
    pop.className = 'sc-color-pop sc-color-pop-compact';
    const swatches = document.createElement('div');
    swatches.className = 'sc-color-swatches';
    MARKER_PALETTE.forEach(function(c) {
        const sw = document.createElement('div');
        sw.className = 'sc-color-swatch' + (c === currentColor ? ' is-active' : '');
        sw.style.background = c;
        sw.title = c;
        sw.setAttribute('aria-label', c);
        sw.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            closeColorPop();
            if (typeof onPick === 'function') onPick(c);
        });
        swatches.appendChild(sw);
    });
    pop.appendChild(swatches);
    const reset = document.createElement('button');
    reset.type = 'button';
    reset.className = 'sc-color-reset-icon';
    reset.title = 'Obnovi? predvolen? farbu';
    reset.setAttribute('aria-label', 'Obnovi? predvolen? farbu');
    reset.textContent = '?';
    reset.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        closeColorPop();
        if (typeof onPick === 'function') onPick(null);
    });
    pop.appendChild(reset);
    document.body.appendChild(pop);
    _colorPopEl = pop;
    const vw = window.innerWidth, vh = window.innerHeight;
    const pw = pop.offsetWidth || 180, ph = pop.offsetHeight || 120;
    const left = Math.max(8, Math.min(Number(x || 0), vw - pw - 8));
    const top = Math.max(8, Math.min(Number(y || 0), vh - ph - 8));
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';
    function onDocClick(e) {
        if (!pop.contains(e.target)) { closeColorPop(); document.removeEventListener('mousedown', onDocClick); }
    }
    setTimeout(function() { document.addEventListener('mousedown', onDocClick); }, 50);
}

// Normal popup: status + name + EUI + [Detail ???] [???]
function buildPopupHtml(name, shortEui, href, mid, tier, slabel) {
    const brandBg  = getComputedStyle(document.documentElement).getPropertyValue('--brand-500').trim() || '#eb7e17';
    const brandHov = getComputedStyle(document.documentElement).getPropertyValue('--brand-600').trim() || '#ca6208';
    const statusColor = tier && STATUS_COLORS[tier] ? STATUS_COLORS[tier] : null;
    const statusBadge = statusColor ? '<div style="display:inline-flex;align-items:center;gap:.26rem;background:' + statusColor + ';color:#fff;border-radius:.3rem;padding:.2rem .4rem;font-size:.62rem;font-weight:700;margin-bottom:.22rem"><span style="width:.32rem;height:.32rem;border-radius:50%;background:currentColor;opacity:.7"></span>' + esc(slabel || tier) + '</div>' : '';
    return '<div style="min-width:168px;font-family:\'Manrope\',system-ui,sans-serif;padding:.05rem 0">'
        + (statusBadge ? statusBadge + '<div style="margin-bottom:.18rem"></div>' : '')
        + '<div style="font-weight:900;font-size:.96rem;color:#0f2135;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:195px;margin-bottom:.2rem">' + name + '</div>'
        + (shortEui ? '<div style="font-size:.63rem;color:#9aaab8;font-family:monospace;letter-spacing:.04em;margin-bottom:.36rem">' + shortEui + '</div>' : '')
        + '<div style="border-top:1px solid #edf2f9;margin:.3rem 0 .38rem"></div>'
        + '<div style="display:flex;align-items:center;gap:.36rem">'
            + '<a href="' + href + '" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:.3rem;background:' + brandBg + ';color:#fff;border-radius:.42rem;padding:.38rem .6rem;font-size:.74rem;font-weight:800;text-decoration:none;border:none;letter-spacing:.01em;transition:background .12s" onmouseover="this.style.background=\'' + brandHov + '\'" onmouseout="this.style.background=\'' + brandBg + '\'">Detail \u2192</a>'
            + '<button id="sc-popup-dots-' + mid + '" class="sc-popup-dots" title="Možnosti">\u22ef</button>'
        + '</div>'
        + '</div>';
}

// Unlocked popup: name + EUI + hint + [Uložiť polohu] [Zrušiť]
function buildPopupUnlockedHtml(name, shortEui, mid, hasMoved) {
    const hintText = hasMoved ? '\u2713 Premiestnený \u2014 uložiť?' : '\u2195 Presuňte marker na novú polohu';
    const hintColor = hasMoved ? '#16a34a' : '#eb7e17';
    return '<div style="min-width:168px;font-family:\'Manrope\',system-ui,sans-serif;padding:.05rem 0">'
        + '<div style="font-weight:900;font-size:.96rem;color:#0f2135;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:195px;margin-bottom:.2rem">' + name + '</div>'
        + (shortEui ? '<div style="font-size:.63rem;color:#9aaab8;font-family:monospace;letter-spacing:.04em;margin-bottom:.24rem">' + shortEui + '</div>' : '')
        + '<div style="font-size:.69rem;font-weight:700;color:' + hintColor + ';margin-bottom:.3rem">' + hintText + '</div>'
        + '<div style="border-top:1px solid #edf2f9;margin:.28rem 0 .36rem"></div>'
        + '<div style="display:flex;gap:.38rem">'
            + (hasMoved ? '<button id="sc-popup-save-' + mid + '" class="sc-popup-save">Uložiť polohu</button>' : '')
            + '<button id="sc-popup-cancel-' + mid + '" class="sc-popup-cancel">Zrušiť</button>'
        + '</div>'
        + '</div>';
}

function updateMap(sensors) {
    if (!mviewMap || !mviewLayer) return;

    // Cancel any pending drags (timeout protection)
    Object.keys(_pendingLatLng).forEach(function(id) {
        if (sensorMarkers[id]) {
            const pending = _pendingLatLng[id];
            sensorMarkers[id].setLatLng([pending._origLat, pending._origLng]);
            showMapToast('Presunutie zrušené (čas vypršal)', 1800);
        }
        delete _pendingLatLng[id];
        _markerUnlocked[id] = false;
    });

    mviewLayer.clearLayers();
    sensorMarkers = {};
    const geo = (sensors || []).filter(function(s) { return !!geoOf(s); });
    if (!geo.length) return;
    const bounds = [];

    geo.forEach(function(s) {
        const latlng = geoOf(s);
        const tier   = SENSOR_TIER(s);
        const statusColor = STATUS_COLORS[tier] || STATUS_COLORS.unknown;
        const id     = sensorId(s);
        const unlocked = !!_markerUnlocked[id];
        const pinColor = s.marker_color || statusColor;
        const name   = esc(s.name || id || 'Unknown');
        const slabel = esc(SENSOR_STATUS_LABEL(s));
        const shortEui = String(id).toUpperCase().replace(/(.{4})(?=.)/g, '$1 ');
        const href   = '/sensors/' + esc(id);

        const marker = L.marker(latlng, {
            icon: makeMarkerIcon(pinColor, unlocked),
            draggable: unlocked,
            autoPan: true
        });

        marker.bindPopup(
            unlocked ? buildPopupUnlockedHtml(name, shortEui, id, !!_pendingLatLng[id])
                     : buildPopupHtml(name, shortEui, href, id, tier, slabel),
            { maxWidth: 240, className: 'sc-leaflet-popup' }
        );

        // Helper: lock and restore normal popup
        function lockMarker() {
            _markerUnlocked[id] = false;
            marker.dragging.disable();
            marker.setIcon(makeMarkerIcon(s.marker_color || statusColor, false));
            marker.setPopupContent(buildPopupHtml(name, shortEui, href, id, tier, slabel));
        }

        // Helper: unlock and show drag popup
        function unlockMarker() {
            _markerUnlocked[id] = true;
            marker.dragging.enable();
            marker.setIcon(makeMarkerIcon(s.marker_color || statusColor, true));
            if (!_pendingLatLng[id]) {
                const cur = marker.getLatLng();
                _pendingLatLng[id] = { _origLat: cur.lat, _origLng: cur.lng, lat: cur.lat, lng: cur.lng };
            }
            marker.setPopupContent(buildPopupUnlockedHtml(name, shortEui, id, false));
            showMapToast('Presúvanie odomknuté \u2014 presuňte marker', 2800);
        }

        // Shared context menu items for right-click and ⋯ button
        function markerCtxItems(cx, cy) {
            const isDragOn = !!_markerUnlocked[id];
            return [
                { icon: 'fa-arrow-up-right-from-square', label: 'Detail senzora',
                    action: function() { window.location.href = '/sensors/' + encodeURIComponent(id); } },
                { icon: isDragOn ? 'fa-lock' : 'fa-lock-open',
                    label: isDragOn ? 'Zamknúť polohu' : 'Odomknúť presúvanie',
                    action: function() { if (!!_markerUnlocked[id]) lockMarker(); else unlockMarker(); } },
                { icon: 'fa-palette', label: 'Zmeniť farbu',
                    action: function() {
                        setTimeout(function() {
                            showColorPop(cx, cy, s.marker_color || null, function(color) {
                                fetch('/api/sensors/' + encodeURIComponent(id) + '/marker-color', {
                                    method: 'POST', headers: {'Content-Type':'application/json'},
                                    body: JSON.stringify({color: color || ''})
                                })
                                .then(function(r) { return r.json(); })
                                .then(function(d) {
                                    if (d.success) {
                                        if (color) s.marker_color = color; else delete s.marker_color;
                                        marker.setIcon(makeMarkerIcon(color || statusColor, !!_markerUnlocked[id]));
                                        showMapToast(color ? '\u2713 Farba zmenená' : '\u2713 Farba obnovená', 2000);
                                    } else {
                                        showMapToast('\u2717 ' + (d.message || 'Chyba'), 2200);
                                    }
                                });
                            });
                        }, 80);
                    } },
                '-',
                { icon: 'fa-circle-plus', primary: true, label: 'Pridať upozornenie',
                    action: function() { window.location.href = buildNewAlertRuleUrl(id); } },
            ];
        }

        // Wire popup buttons every time popup opens
        marker.on('popupopen', function() {
            // Block right-click on popup
            const popupEl = document.querySelector('.leaflet-popup');
            if (popupEl) {
                popupEl.addEventListener('contextmenu', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                });
            }

            // ⋯ dots button (normal popup)
            const dotsBtn = document.getElementById('sc-popup-dots-' + id);
            if (dotsBtn) {
                dotsBtn.addEventListener('click', function(e) {
                    e.stopPropagation();
                    const rect = dotsBtn.getBoundingClientRect();
                    const fakeEv = {
                        clientX: rect.left, clientY: rect.bottom + 4,
                        preventDefault: function(){}, stopPropagation: function(){}
                    };
                    showCtx(fakeEv, markerCtxItems(rect.left, rect.bottom + 8));
                });
            }

            // Save / cancel buttons (unlocked popup after drag)
            const saveBtn   = document.getElementById('sc-popup-save-' + id);
            const cancelBtn = document.getElementById('sc-popup-cancel-' + id);

            if (saveBtn) {
                saveBtn.addEventListener('click', function() {
                    const pending = _pendingLatLng[id];
                    if (!pending) return;
                    marker.closePopup();
                    fetch('/api/sensors/' + encodeURIComponent(id) + '/gps', {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({gps_lat: pending.lat, gps_lng: pending.lng})
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(d) {
                        if (d.success) {
                            const sr = allSensors.find(function(x) { return sensorId(x) === id; });
                            if (sr) { sr.gps_lat = pending.lat; sr.gps_lng = pending.lng; }
                            showMapToast('\u2713 Poloha uložená', 2400);
                        } else {
                            marker.setLatLng([pending._origLat, pending._origLng]);
                            showMapToast('\u2717 ' + (d.message || 'Chyba uloženia'), 2400);
                        }
                        delete _pendingLatLng[id];
                        lockMarker();
                    })
                    .catch(function() {
                        const pending2 = _pendingLatLng[id];
                        if (pending2) marker.setLatLng([pending2._origLat, pending2._origLng]);
                        showMapToast('\u2717 Chyba uloženia', 2400);
                        delete _pendingLatLng[id];
                        lockMarker();
                    });
                });
            }

            if (cancelBtn) {
                cancelBtn.addEventListener('click', function() {
                    const pending = _pendingLatLng[id];
                    if (pending) marker.setLatLng([pending._origLat, pending._origLng]);
                    delete _pendingLatLng[id];
                    marker.closePopup();
                    lockMarker();
                    showMapToast('Presunutie zrušené', 1800);
                });
            }
        });

        marker.on('click', function() { highlightRow(id); });

        marker.on('dragstart', function() {
            marker.closePopup();
            // Save original only on first drag (preserve across multiple drags)
            if (!_pendingLatLng[id]) {
                const cur = marker.getLatLng();
                _pendingLatLng[id] = { _origLat: cur.lat, _origLng: cur.lng, lat: cur.lat, lng: cur.lng };
            }
        });

        marker.on('dragend', function(e) {
            const ll = e.target.getLatLng();
            // Update pending position but KEEP unlocked — user may drag again
            if (_pendingLatLng[id]) { _pendingLatLng[id].lat = ll.lat; _pendingLatLng[id].lng = ll.lng; }
            // Show unlocked popup with save/cancel
            marker.setPopupContent(buildPopupUnlockedHtml(name, shortEui, id, true));
            marker.openPopup();
        });

        // Right-click: same context menu
        marker.on('contextmenu', function(e) {
            L.DomEvent.preventDefault(e.originalEvent);
            L.DomEvent.stopPropagation(e.originalEvent);
            showCtx(e.originalEvent, markerCtxItems(e.originalEvent.clientX, e.originalEvent.clientY));
        });

        marker.addTo(mviewLayer);
        sensorMarkers[id] = marker;
        bounds.push(latlng);
    });

    // Don't reset map view — user controls zoom/pan, saved to localStorage
}
// ── End marker helpers ────────────────────────────────────────────────────────

/* ── List ↔ Map linking ── */
function highlightRow(id) {
    document.querySelectorAll('.mview-sensor-row').forEach(function(r) {
        r.classList.toggle('is-highlighted', r.dataset.sensorId === id);
    });
    const row = document.querySelector('.mview-sensor-row[data-sensor-id="' + id + '"]');
    if (row) row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    // Highlight pin on map
    Object.entries(sensorMarkers).forEach(function(kv) {
        const el = kv[1].getElement();
        const pin = el && el.querySelector('.sc-map-pin');
        if (pin) pin.classList.toggle('is-highlighted', kv[0] === id);
    });
}

function focusOnMap(id) {
    const marker = sensorMarkers[id];
    if (marker && mviewMap) {
        mviewMap.setView(marker.getLatLng(), Math.max(mviewMap.getZoom(), 15));
        marker.openPopup();
    }
    highlightRow(id);
}
window.focusOnMap = focusOnMap;

/* ── Filter ── */
function applyFilter(sensors) {
    return currentFilter === 'all'
        ? sensors
        : sensors.filter(function(s) { return SENSOR_TIER(s) === currentFilter; });
}

function setFilter(f) {
    currentFilter = f;
    document.querySelectorAll('.mview-filter').forEach(function(btn) {
        btn.classList.toggle('is-active', btn.dataset.filter === f);
    });
    const filtered = applyFilter(allSensors);
    renderList(filtered);
    updateMap(filtered);
}
window.mviewSetFilter = setFilter;

/* ── Render list ── */
function renderList(sensors) {
    const el = document.getElementById('mviewSensorList');
    if (!el) return;
    if (!sensors.length) {
        el.innerHTML = '<div class="text-center text-muted py-4" style="font-size:0.85rem;">' +
            (currentFilter === 'all' ? 'Žiadne senzory' : 'Žiadne výsledky') + '</div>';
        return;
    }
    el.innerHTML = sensors.map(function(s) {
        const raw    = s.activity_status || s.status || 'unknown';
        const tier   = SENSOR_TIER(s);
        const name   = esc(s.name || s.eui || s.device_eui || s.sensor_id || '\u2014');
        const slabel = esc(SENSOR_STATUS_LABEL(s));
        const id     = sensorId(s);
        const href   = '/sensors/' + esc(id);
        const sub    = valueLine(s);
        const chips  = buildMetricChipsHtml(s);
        const hasMetrics = chips.length > 0;
        return '<div class="mview-sensor-row' + (hasMetrics ? ' has-metrics' : '') + '" data-sensor-id="' + esc(id) + '" onclick="focusOnMap(\'' + esc(id) + '\')">' +
            '<span class="mview-dot ' + tier + '"></span>' +
            '<span class="mview-sensor-info">' +
                '<span class="mview-sensor-name">' + name + '</span>' +
                (sub && !hasMetrics ? '<span class="mview-sensor-sub">' + sub + '</span>' : '') +
                (hasMetrics ? '<div class="mview-metrics">' + chips + '</div>' : '') +
            '</span>' +
            '<span class="mview-badge ' + tier + '">' + slabel + '</span>' +
            (hasMetrics ? '<button class="mview-expand-btn" onclick="toggleMetricsDrop(\'' + esc(id) + '\',event)" title="Zobraziť metriky"><i class="fas fa-chevron-down"></i></button>' : '') +
            '<a href="' + href + '" class="mview-sensor-link" onclick="event.stopPropagation()" title="Detail">' +
                '<i class="fas fa-chevron-right"></i>' +
            '</a>' +
        '</div>' +
        (hasMetrics ? '<div class="mview-metrics-drop" id="mdrop-' + esc(id) + '">' + chips + '</div>' : '');
    }).join('');
}

/* ── Metric drop toggle ── */
function toggleMetricsDrop(id, e) {
    e.stopPropagation();
    const drop = document.getElementById('mdrop-' + id);
    const btn  = e.currentTarget;
    if (!drop) return;
    const open = drop.classList.toggle('is-open');
    btn.classList.toggle('is-open', open);
}

/* ── User menu toggle ── */
function toggleUserMenu() {
    const dropdown = document.getElementById('mviewUserDropdown');
    if (!dropdown) return;
    const isOpen = dropdown.classList.toggle('is-open');
    if (isOpen) {
        document.addEventListener('mousedown', closeUserMenuOnClick);
    } else {
        document.removeEventListener('mousedown', closeUserMenuOnClick);
    }
}
function closeUserMenuOnClick(e) {
    const menu = document.querySelector('.mview-user-menu');
    if (!menu || menu.contains(e.target)) return;
    const dropdown = document.getElementById('mviewUserDropdown');
    if (dropdown) {
        dropdown.classList.remove('is-open');
        document.removeEventListener('mousedown', closeUserMenuOnClick);
    }
}

/* ── Panel width → narrow class ── */
function initNarrowObserver() {
    const panel = document.querySelector('.mview-list-panel');
    if (!panel || typeof ResizeObserver === 'undefined') return;
    new ResizeObserver(function(entries) {
        const w = entries[0].contentRect.width;
        panel.classList.toggle('is-narrow', w < 300);
    }).observe(panel);
}

/* ── Live tick ── */
function startTick() {
    if (tickTimer) clearInterval(tickTimer);
    lastLoadTs = Date.now();
}

/* ── Alerts ── */
const COND_LABEL_DASH = {'gt':'>','gte':'≥','lt':'<','lte':'≤','eq':'='};
const METRIC_UNIT_DASH = {co2_1_ppm:'ppm',co2_2_ppm:'ppm',temperature_1_c:'°C',temperature_2_c:'°C',humidity_1_pct:'%',battery_v_est:'V'};
const METRIC_NAMES_DASH = {co2_1_ppm:'CO₂',co2_2_ppm:'CO₂ (predch.)',temperature_1_c:'Teplota',temperature_2_c:'Teplota 2',humidity_1_pct:'Vlhkosť',battery_v_est:'Batéria',any_alarm_active:'Alarm aktívny',alarm_count:'Počet alarmov',open_count:'Počet otvorení'};

function renderAlerts() {
    const body  = document.getElementById('mviewAlerts');
    const badge = document.getElementById('mviewAlertsBadge');
    const head  = document.getElementById('mviewAlertsHead');
    if (!body) return;

    fetch('/api/incidents')
        .then(function(r) { return r.ok ? r.json() : {incidents:[]}; })
        .catch(function() { return {incidents:[]}; })
        .then(function(d) {
            const incidents = Array.isArray(d.incidents) ? d.incidents : [];
            const visible = incidents.filter(function(item) { return !item.ackKey || !isAcked(item.ackKey); });
            const hasError = visible.some(function(item) { return item.tier === 'error'; });
            const hasWarn  = visible.some(function(item) { return item.tier === 'warn'; });
            if (head) {
                head.classList.toggle('has-error', hasError);
                head.classList.toggle('has-warn', !hasError && hasWarn);
            }
            if (badge) {
                badge.textContent = visible.length || '';
                badge.classList.toggle('is-visible', visible.length > 0);
            }
            if (!visible.length) {
                body.innerHTML = '<div class="mview-alerts-empty">Žiadne upozornenia</div>';
                return;
            }
            body.innerHTML = visible.map(function(item) {
                const href = item.linkUrl || (item.eui ? '/sensors/' + encodeURIComponent(item.eui) : '/alerts');
                const icon = item.tier === 'error'
                    ? (item.source === 'threshold' ? 'fa-bell' : 'fa-circle-xmark')
                    : (item.source === 'threshold' ? 'fa-bell' : 'fa-triangle-exclamation');
                return '<a class="mview-alert-row is-' + item.tier + '" href="' + href + '"'
                    + ' data-eui="' + esc(item.eui || '') + '" data-ack-key="' + esc(item.ackKey || '') + '">' +
                    '<i class="fas ' + icon + ' mview-alert-icon"></i>' +
                    '<div class="mview-alert-info">' +
                        '<div class="mview-alert-name">' + esc(item.name || 'Incident') + '</div>' +
                        '<div class="mview-alert-desc">' + esc(item.desc || item.text || '') + '</div>' +
                    '</div>' +
                    '<i class="fas fa-chevron-right" style="font-size:.58rem;color:#cbd5e1;flex-shrink:0"></i>' +
                '</a>';
            }).join('');
        });
}

/* ── Load ── */
function load() {
    fetch('/api/sensors')
        .then(function(r) { return r.ok ? r.json() : null; })
        .catch(function() { return null; })
        .then(function(data) {
            const raw = Array.isArray(data) ? data
                : (data && Array.isArray(data.sensors) ? data.sensors
                : (data && typeof data === 'object' && !data.error ? Object.values(data) : []));

            // Sort: offline → warn → online
            raw.sort(function(a, b) {
                return (TIER_ORDER[SENSOR_TIER(a)] || 3) - (TIER_ORDER[SENSOR_TIER(b)] || 3);
            });
            allSensors = raw;

            let online = 0, warn = 0, offline = 0;
            raw.forEach(function(s) {
                const t = SENSOR_TIER(s);
                if (t === 'online') online++;
                else if (t === 'warn') warn++;
                else if (t === 'offline') offline++;
            });

            // KPI counts
            function g(id) { return document.getElementById(id); }
            // Filter counts
            if (g('mviewFiltAll'))     g('mviewFiltAll').textContent     = raw.length;
            if (g('mviewFiltOnline'))  g('mviewFiltOnline').textContent  = online;
            if (g('mviewFiltWarn'))    g('mviewFiltWarn').textContent    = warn;
            if (g('mviewFiltOffline')) g('mviewFiltOffline').textContent = offline;

            // Render
            const filtered = applyFilter(raw);
            renderList(filtered);
            updateMap(filtered);
            renderAlerts(raw);
            startTick();
        });
}

/* ── Resizable panel ── */
const MVIEW_WIDTH_KEY = 'service-center.mview-list-width.v1';

function initResizer() {
    const resizer  = document.getElementById('mviewResizer');
    const panel    = document.querySelector('.mview-list-panel');
    const split    = document.querySelector('.mview-split');
    if (!resizer || !panel || !split) return;

    // Restore saved width
    try {
        const saved = parseInt(localStorage.getItem(MVIEW_WIDTH_KEY), 10);
        if (saved >= 220) panel.style.width = saved + 'px';
    } catch (e) {}

    function applyWidth(px) {
        const max = split.offsetWidth * 0.65;
        const clamped = Math.max(220, Math.min(px, max));
        panel.style.width = clamped + 'px';
        return clamped;
    }

    // Mouse
    resizer.addEventListener('mousedown', function(e) {
        const startX     = e.clientX;
        const startWidth = panel.offsetWidth;
        resizer.classList.add('is-dragging');
        document.body.style.cursor     = 'col-resize';
        document.body.style.userSelect = 'none';

        function onMove(e) {
            applyWidth(startWidth + (e.clientX - startX));
            if (mviewMap) mviewMap.invalidateSize();
        }
        function onUp() {
            resizer.classList.remove('is-dragging');
            document.body.style.cursor     = '';
            document.body.style.userSelect = '';
            try { localStorage.setItem(MVIEW_WIDTH_KEY, panel.offsetWidth); } catch (e) {}
            if (mviewMap) mviewMap.invalidateSize();
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup',   onUp);
        }
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup',   onUp);
        e.preventDefault();
    });

    // Touch
    resizer.addEventListener('touchstart', function(e) {
        const startX     = e.touches[0].clientX;
        const startWidth = panel.offsetWidth;

        function onMove(e) {
            applyWidth(startWidth + (e.touches[0].clientX - startX));
            if (mviewMap) mviewMap.invalidateSize();
        }
        function onEnd() {
            try { localStorage.setItem(MVIEW_WIDTH_KEY, panel.offsetWidth); } catch (e) {}
            resizer.removeEventListener('touchmove', onMove);
            resizer.removeEventListener('touchend',  onEnd);
        }
        resizer.addEventListener('touchmove', onMove, { passive: true });
        resizer.addEventListener('touchend',  onEnd);
    }, { passive: true });
}

/* ── Vertical resizer (list ↕ alerts) ── */
const MVIEW_ALERTS_HEIGHT_KEY = 'service-center.mview-alerts-height.v1';

function initVResizer() {
    const resizer = document.getElementById('mviewVResizer');
    const listEl  = document.querySelector('.mview-list-body');
    const alertEl = document.querySelector('.mview-alerts-panel');
    const panel   = document.querySelector('.mview-list-panel');
    if (!resizer || !listEl || !alertEl || !panel) return;

    // Switch both to fixed pixel heights so we can resize them
    function applyHeight(alertPx) {
        const total = panel.offsetHeight
            - (panel.querySelector('.mview-list-head')?.offsetHeight  || 0)
            - (panel.querySelector('.mview-filters')?.offsetHeight    || 0)
            - resizer.offsetHeight;
        const clamped = Math.max(60, Math.min(alertPx, total - 60));
        alertEl.style.flex = 'none';
        alertEl.style.height = clamped + 'px';
        listEl.style.flex = 'none';
        listEl.style.height = (total - clamped) + 'px';
        return clamped;
    }

    // Restore saved height
    try {
        const saved = parseInt(localStorage.getItem(MVIEW_ALERTS_HEIGHT_KEY), 10);
        if (saved >= 60) applyHeight(saved);
    } catch (e) {}

    // Mouse
    resizer.addEventListener('mousedown', function(e) {
        const startY      = e.clientY;
        const startHeight = alertEl.offsetHeight;
        resizer.classList.add('is-dragging');
        document.body.style.cursor     = 'row-resize';
        document.body.style.userSelect = 'none';

        function onMove(e) { applyHeight(startHeight - (e.clientY - startY)); }
        function onUp() {
            resizer.classList.remove('is-dragging');
            document.body.style.cursor     = '';
            document.body.style.userSelect = '';
            try { localStorage.setItem(MVIEW_ALERTS_HEIGHT_KEY, alertEl.offsetHeight); } catch (e) {}
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup',   onUp);
        }
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup',   onUp);
        e.preventDefault();
    });

    // Touch
    resizer.addEventListener('touchstart', function(e) {
        const startY      = e.touches[0].clientY;
        const startHeight = alertEl.offsetHeight;
        function onMove(e) { applyHeight(startHeight - (e.touches[0].clientY - startY)); }
        function onEnd() {
            try { localStorage.setItem(MVIEW_ALERTS_HEIGHT_KEY, alertEl.offsetHeight); } catch (e) {}
            resizer.removeEventListener('touchmove', onMove);
            resizer.removeEventListener('touchend',  onEnd);
        }
        resizer.addEventListener('touchmove', onMove, { passive: true });
        resizer.addEventListener('touchend',  onEnd);
    }, { passive: true });
}

// ── Context menu ────────────────────────────────────────────────────────────
const SC_ACKS_KEY = 'sc.alert-acks.v1';

function _loadAcks() {
    try { return JSON.parse(localStorage.getItem(SC_ACKS_KEY)) || []; } catch(e) { return []; }
}
function _saveAcks(acks) {
    try { localStorage.setItem(SC_ACKS_KEY, JSON.stringify(acks)); } catch(e) {}
}
function isAcked(key) {
    const now = Date.now();
    return _loadAcks().some(function(a) { return a.key === key && a.until > now; });
}
function ackAlert(key, hours) {
    const acks = _loadAcks().filter(function(a) { return a.key !== key; });
    acks.push({ key: key, until: Date.now() + hours * 3600000 });
    _saveAcks(acks);
}

let _ctxEl = null;
function closeCtx() { if (_ctxEl) { _ctxEl.remove(); _ctxEl = null; } }

function showCtx(e, items) {
    e.preventDefault();
    closeCtx();
    const menu = document.createElement('div');
    menu.className = 'sc-ctx';
    menu.tabIndex = -1;
    items.forEach(function(item) {
        if (item === '-') {
            const sep = document.createElement('div');
            sep.className = 'sc-ctx-sep';
            menu.appendChild(sep);
            return;
        }
        const el = document.createElement('div');
        el.className = 'sc-ctx-item'
            + (item.primary ? ' is-primary' : '')
            + (item.danger ? ' is-danger' : '');
        el.innerHTML = '<i class="fas ' + item.icon + '"></i>' + esc(item.label);
        el.addEventListener('click', function() { closeCtx(); item.action(); });
        menu.appendChild(el);
    });

    // Position: keep inside viewport
    document.body.appendChild(menu);
    _ctxEl = menu;
    const vw = window.innerWidth, vh = window.innerHeight;
    const mw = menu.offsetWidth, mh = menu.offsetHeight;
    let x = e.clientX, y = e.clientY;
    if (x + mw > vw - 8) x = vw - mw - 8;
    if (y + mh > vh - 8) y = vh - mh - 8;
    menu.style.left = x + 'px';
    menu.style.top  = y + 'px';
    menu.focus();
}

document.addEventListener('click', closeCtx);
document.addEventListener('keydown', function(e) { if (e.key === 'Escape') closeCtx(); });

function initContextMenus() {
    function buildNewAlertRuleUrl(sensorEui) {
        const params = new URLSearchParams();
        params.set('tab', 'rules');
        params.set('new_rule', '1');
        if (sensorEui) params.set('sensor', String(sensorEui).toUpperCase());
        params.set('return_to', window.location.pathname + window.location.search + window.location.hash);
        return '/alerts?' + params.toString();
    }

    // Right-click on sensor list panel (rows + empty space)
    const sensorList = document.getElementById('mviewSensorList');
    if (sensorList) {
        sensorList.addEventListener('contextmenu', function(e) {
            const row = e.target.closest('.mview-sensor-row');
            if (row) {
                const eui = row.dataset.sensorId || '';
                showCtx(e, [
                    { icon: 'fa-arrow-up-right-from-square', label: 'Otvoriť detail', action: function() { window.location.href = '/sensors/' + encodeURIComponent(eui); } },
                    { icon: 'fa-circle-plus', primary: true, label: 'Pridať upozornenie', action: function() { window.location.href = buildNewAlertRuleUrl(eui); } },
                ]);
            } else {
                // Empty area
                showCtx(e, [
                    { icon: 'fa-plus', label: 'Pridať senzor', action: function() { window.location.href = '/sensors?add=1'; } },
                ]);
            }
        });
    }

    // Right-click on alerts panel (rows + empty space)
    const alertsPanel = document.querySelector('.mview-alerts-panel');
    if (alertsPanel) {
        alertsPanel.addEventListener('contextmenu', function(e) {
            const row = e.target.closest('.mview-alert-row');
            if (row) {
                const eui    = row.dataset.eui    || '';
                const ackKey = row.dataset.ackKey || '';
                showCtx(e, [
                    { icon: 'fa-clock-rotate-left', label: 'Potvrdiť na 4 hodiny',  action: function() { if (ackKey) { ackAlert(ackKey, 4);  renderAlerts(allSensors); } } },
                    { icon: 'fa-check-double',       label: 'Potvrdiť na 24 hodín', action: function() { if (ackKey) { ackAlert(ackKey, 24); renderAlerts(allSensors); } } },
                    '-',
                    { icon: 'fa-arrow-up-right-from-square', label: 'Otvoriť senzor', action: function() { if (eui) window.location.href = '/sensors/' + encodeURIComponent(eui); } },
                ]);
            } else {
                // Empty area / header
                showCtx(e, [
                    { icon: 'fa-circle-plus', primary: true, label: 'Pridať upozornenie', action: function() { window.location.href = buildNewAlertRuleUrl(''); } },
                ]);
            }
        });
    }
}
// ── End context menu ─────────────────────────────────────────────────────────

initResizer();
initVResizer();
initContextMenus();
initNarrowObserver();
initMap();
load();
setInterval(load, 30000);
})();
